h, w = len(test_input), len(test_input[0])

def find_3x3_blocks(grid):
    """Find all complete 3x3 blocks of the same color"""
    blocks = {}
    all_cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                color = grid[r][c]
                if color not in all_cells:
                    all_cells[color] = []
                all_cells[color].append((r, c))

    for color, cells in all_cells.items():
        for tr in range(h - 2):
            for tc in range(w - 2):
                expected = set()
                for dr in range(3):
                    for dc in range(3):
                        expected.add((tr + dr, tc + dc))
                actual = set((r, c) for r, c in cells if tr <= r < tr + 3 and tc <= c < tc + 3)
                if actual == expected:
                    blocks.setdefault(color, []).append({'center_r': tr + 1, 'center_c': tc + 1})

    return blocks

blocks = find_3x3_blocks(test_input)
print("3x3 blocks found:")
for color, block_list in sorted(blocks.items()):
    print(f"  Color {color}: centers at {[(b['center_r'], b['center_c']) for b in block_list]}")

# Generate output by filling rows/cols of 3x3 block centers
output = [row[:] for row in test_input]

for color, block_list in sorted(blocks.items()):
